VOICE_CHOICES = tuple(voice["display"] for voice in MINIMAX_SYSTEM_VOICES)
DEFAULT_VOICE_CHOICE = VOICE_CHOICES[0]

_VOICE_ID_BY_DISPLAY = {voice["display"]: voice["voice_id"] for voice in MINIMAX_SYSTEM_VOICES}


def resolve_voice_id(value: str) -> str:
    """Resolve a catalog display label while preserving valid custom Voice IDs."""

    normalized = str(value or "").strip()
    if not normalized:
        return ""
    return _VOICE_ID_BY_DISPLAY.get(normalized, normalized)


